// ICNS container fallback for environments where iconutil's encoder is unavailable.
// The PNG representations are generated by sips; their pixels are not modified here.
import Foundation
import ImageIO

func bigEndian(_ value: Int) -> Data {
    var number = UInt32(value).bigEndian
    return withUnsafeBytes(of: &number) { Data($0) }
}

let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
let representations = [
    ("icp4", "icon_16x16.png"), ("icp5", "icon_32x32.png"),
    ("ic11", "icon_16x16@2x.png"), ("ic12", "icon_32x32@2x.png"),
    ("ic07", "icon_128x128.png"), ("ic08", "icon_256x256.png"),
    ("ic13", "icon_128x128@2x.png"), ("ic14", "icon_256x256@2x.png"),
    ("ic09", "icon_512x512.png"), ("ic10", "icon_512x512@2x.png")
]
var body = Data()
for (type, name) in representations {
    let png = try Data(contentsOf: root.appendingPathComponent(name))
    body.append(Data(type.utf8))
    body.append(bigEndian(png.count + 8))
    body.append(png)
}
var icon = Data("icns".utf8)
icon.append(bigEndian(body.count + 8))
icon.append(body)
guard let decoded = CGImageSourceCreateWithData(icon as CFData, nil), CGImageSourceGetCount(decoded) > 0 else {
    fatalError("ICNS could not be decoded by ImageIO")
}
for index in 0..<CGImageSourceGetCount(decoded) {
    precondition(CGImageSourceCreateImageAtIndex(decoded, index, nil) != nil, "Invalid ICNS representation")
}
try icon.write(to: URL(fileURLWithPath: CommandLine.arguments[2]), options: .atomic)
print("ICNS validado pelo ImageIO: \(CGImageSourceGetCount(decoded)) representações")
